        'Verify' => 'Xác nhận',
        'Having Problems?' => 'Không lấy được mã?',
        'Use a recovery code' => 'Dùng mã dự phòng',
        'Use %s' => 'Dùng %s',
        'Enter a recovery code.' => 'Nhập một mã dự phòng. Mỗi mã chỉ dùng được một lần.',
