        'Revalidate now' => 'Xác thực lại ngay',
        'Two Factor Revalidation required.' => 'Cần xác thực lại hai lớp.',
        'You have revalidated successfully.' => 'Đã xác thực lại thành công.',
        'No providers are available for your account.' => 'Tài khoản chưa có phương thức xác thực nào.',
    ];
