add_filter('gettext_two-factor', function ($translation, $text) {
    $d = nhom25_2fa_dich();
    return $d[$text] ?? $translation;
}, 10, 2);

add_filter('gettext_with_context_two-factor', function ($translation, $text, $context) {
    $nhan = ['Authenticator App' => 'Ứng dụng xác thực (TOTP)', 'Recovery Codes' => 'Mã dự phòng', 'Email' => 'Email'];
    return $context === 'Provider Label' && isset($nhan[$text]) ? $nhan[$text] : $translation;
}, 10, 3);

add_filter('ngettext_two-factor', function ($translation, $single) {
    return strpos($single, 'unused code remaining') !== false ? '%s mã chưa dùng, mỗi mã chỉ dùng được một lần.' : $translation;
}, 10, 2);

// Logo trang dang nhap tro ve cua hang, khong tro ve wordpress.org
add_filter('login_headerurl', function () {
    return home_url('/');
});
add_filter('login_headertext', function () {
    return get_bloginfo('name');
});

// Giao dien trang dang nhap (ca buoc nhap mat khau va buoc nhap ma 2FA)
add_action('login_enqueue_scripts', function () {
    ?>
    <style id="nhom25-dang-nhap">
        body.login {
            background: #f6f8fa;
            color: #13304d;
            font-family: -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
        }
        body.login #login { width: 380px; padding-top: 7vh; }
        body.login h1 a {
            background: none; width: auto; height: auto; text-indent: 0; overflow: visible;
            font-size: 30px; font-weight: 700; line-height: 1.2; color: #13304d; margin: 0 0 20px;
        }
        body.login h1 a::after {
            content: "Cửa hàng đồ dùng học tập"; display: block;
            font-size: 14px; font-weight: 400; color: #5a6b7b; margin-top: 4px;
        }
        body.login h1 a:focus { box-shadow: none; outline: 2px solid #2a9d8f; outline-offset: 4px; border-radius: 6px; }
        body.login form {
            border: 0; border-top: 4px solid #2a9d8f; border-radius: 14px;
            box-shadow: 0 10px 30px rgba(19, 48, 77, .10); padding: 26px 28px 30px;
        }
        body.login form p, body.login form label { color: #13304d; }
        body.login label { font-weight: 600; }
        body.login input[type=text], body.login input[type=password], body.login input[type=email] {
            border: 1px solid #c9d4dd; border-radius: 8px; box-shadow: none;
        }
        body.login input[type=text]:focus, body.login input[type=password]:focus {
            border-color: #2a9d8f; box-shadow: 0 0 0 2px rgba(42, 157, 143, .25);
        }
        body.login .wp-core-ui .button-primary, body.login .button-primary {
            background: #13304d; border-color: #13304d; border-radius: 8px;
            padding: 0 22px; font-weight: 600; box-shadow: none; text-shadow: none;
        }
        body.login .button-primary:hover, body.login .button-primary:focus {
            background: #1f6e8c; border-color: #1f6e8c;
        }
        body.login .button.wp-hide-pw .dashicons { color: #1f6e8c; }
        body.login #login_error, body.login .message, body.login .notice {
            border-radius: 10px; border-left-width: 4px; box-shadow: 0 4px 14px rgba(19, 48, 77, .06);
        }
        body.login .message, body.login .notice-info { border-left-color: #2a9d8f; }
        body.login #nav, body.login #backtoblog { text-align: center; padding: 0; }
        body.login #nav a, body.login #backtoblog a, body.login .privacy-policy-link { color: #1f6e8c; }
        body.login #nav a:hover, body.login #backtoblog a:hover { color: #13304d; }

        /* Buoc nhap ma 2FA */
        body.login #loginform > p:first-of-type:not(:has(input)) { color: #3c4b59; line-height: 1.55; margin-bottom: 18px; }
        body.login #loginform .input.authcode {
            font-size: 30px; letter-spacing: .4em; text-align: center; padding: 10px 6px 10px 18px;
            border-radius: 10px; font-variant-numeric: tabular-nums; margin-top: 6px;
        }
        body.login #loginform .input.authcode::placeholder { color: #b8c4ce; letter-spacing: .4em; }
        body.login #loginform input[name=two-factor-backup-code] { font-size: 22px; letter-spacing: .15em; text-align: center; }
        body.login #loginform .button-primary { width: 100%; height: 42px; margin-top: 8px; font-size: 15px; }
        body.login .backup-methods-wrap {
            margin-top: 16px !important; padding: 18px 28px !important; background: #ffffff;
            border-radius: 14px; box-shadow: 0 6px 20px rgba(19, 48, 77, .07);
        }
        body.login .backup-methods-wrap p { color: #5a6b7b; margin: 0 0 8px !important; font-weight: 600; }
        body.login .backup-methods-wrap ul { list-style: none; margin: 0 !important; padding: 0 !important; }
        body.login .backup-methods-wrap li { margin: 0; }
        body.login .backup-methods-wrap a { color: #1f6e8c; font-weight: 600; text-decoration: none; }
        body.login .backup-methods-wrap a::before { content: "→ "; }
        body.login .backup-methods-wrap a:hover { color: #13304d; text-decoration: underline; }
    </style>
    <?php
});
